input.query:
SELECT p.product_ndc, p.name, p.clinical_drug_iri, 'ing' src FROM product p JOIN product__ingredients pi ON pi.owner_iri=p.iri JOIN substance s ON s.iri=pi.substance_iri WHERE s.unii='68JRS2HC1C'
UNION ALL
SELECT p.product_ndc, p.name, p.clinical_drug_iri, 'moiety' FROM product p JOIN product__ingredients pi ON pi.owner_iri=p.iri JOIN substance__active_moiety am ON am.owner_iri=pi.substance_iri JOIN substance m ON m.iri=am.moiety_iri WHERE m.unii='68JRS2HC1C';

