input.query:
SELECT (SELECT count(*) FROM clinical_drug WHERE rxcui='1724341') AS cd_count,
 (SELECT count(*) FROM product p WHERE p.clinical_drug_iri IN (SELECT iri FROM clinical_drug WHERE rxcui='1724341')) AS direct,
 (SELECT count(*) FROM product__drug_mappings m JOIN clinical_drug c ON c.iri=m.clinical_drug_iri WHERE c.rxcui='1724341') AS mapped;

