input.query:
WITH s AS (
  SELECT iri FROM substance WHERE name ILIKE '%orphenadrine%'
  UNION
  SELECT am.owner_iri FROM substance__active_moiety am JOIN substance m ON m.iri = am.moiety_iri WHERE m.name ILIKE '%orphenadrine%'
),
p AS (
  SELECT DISTINCT pi.owner_iri AS product_iri FROM product__ingredients pi WHERE pi.substance_iri IN (SELECT iri FROM s)
),
r AS (
  SELECT DISTINCT rc.recalling_firm_iri AS firm FROM recall rc JOIN recall__products rp ON rp.owner_iri = rc.iri WHERE rp.target_iri IN (SELECT product_iri FROM p)
)
SELECT o.iri, o.name FROM organization o WHERE o.iri IN (SELECT firm FROM r) ORDER BY o.name;

