input.query:
SELECT p.iri, p.product_ndc, p.name, 'cd' AS src FROM product p JOIN clinical_drug c ON c.iri=p.clinical_drug_iri WHERE c.rxcui='898356'
UNION ALL
SELECT p.iri, p.product_ndc, p.name, 'map' FROM product__drug_mappings m JOIN product p ON p.iri=m.owner_iri JOIN clinical_drug c ON c.iri=m.clinical_drug_iri WHERE c.rxcui='898356';

