input.query:
select s.iri, s.unii, s.name from substance s where s.unii='VZI5B1W380'
union all
select p.iri, p.product_ndc, p.name from product p join product__ingredients pi on pi.owner_iri=p.iri join substance s on s.iri=pi.substance_iri where s.unii='VZI5B1W380';

