SELECT s.unii, s.name, (SELECT count(*) FROM product__ingredients pi WHERE pi.substance_iri=s.iri) AS direct_products,
 (SELECT count(*) FROM substance__active_moiety am WHERE am.moiety_iri=s.iri) AS salt_forms
FROM substance s WHERE s.unii='NMH84OZK2B' OR s.name ILIKE '%ondansetron%';

