SELECT p.iri, p.product_ndc, p.name, p.clinical_drug_iri FROM product p WHERE p.product_ndc = '0264-3195'
UNION ALL
SELECT p.iri, 'map:'||m.clinical_drug_iri, m.source, NULL FROM product p JOIN product__drug_mappings m ON m.owner_iri=p.iri WHERE p.product_ndc = '0264-3195';

