input.query:
MATCH (r:AdverseEventReport)-[:DRUG_INVOLVEMENT]->(d:DrugInvolvement)
WHERE EXISTS { MATCH (d)-[:CLINICAL_DRUG]->(c:ClinicalDrug) WHERE c.rxcui IN ['2568573','2568579'] }
   OR EXISTS { MATCH (d)-[:HARMONIZED_CLINICAL_DRUG]->(h:ClinicalDrug) WHERE h.rxcui IN ['2568573','2568579'] }
RETURN r.report_id AS id, r.serious AS serious, r.receipt_date AS dt, r.iri AS iri

